import { Group, Mesh, PlaneGeometry, Color, DoubleSide, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, smoothstep, float, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new Group();
  group.userData.handlers = {};

  const specColors = config?.intent?.visualSpec?.colors ?? config?.colors ?? {};
  const accent = new Color(specColors.accent ?? '#ff2a38');
  const surface = new Color(specColors.surface ?? '#0b0b10');

  // Inner group for hover/press transforms (separate from parallax on outer)
  const inner = new Group();
  group.add(inner);

  const cardW = 2.4;
  const cardH = cardW * (320 / 512);

  // --- Depth plane 1 (back): accent radial glow ---
  const glowGeo = new PlaneGeometry(cardW * 1.5, cardH * 1.5);
  const glowMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    colorNode: vec3(float(accent.r), float(accent.g), float(accent.b)),
    opacityNode: float(1.0)
      .sub(smoothstep(float(0.0), float(0.5), uv().sub(float(0.5)).length()))
      .mul(float(0.14)),
  });
  glowMat.opacity = 0;
  const glowMesh = new Mesh(glowGeo, glowMat);
  glowMesh.position.z = -0.22;
  inner.add(glowMesh);

  // --- Depth plane 1b (back): dark backdrop for depth ---
  const backdropGeo = new PlaneGeometry(cardW * 1.1, cardH * 1.1);
  const backdropMat = new MeshBasicNodeMaterial({
    color: surface,
    transparent: true,
    depthWrite: false,
  });
  backdropMat.opacity = 0;
  const backdropMesh = new Mesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0.09, -0.09, -0.1);
  inner.add(backdropMesh);

  // --- Depth plane 2 (front): main textured card ---
  const cardMat = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
    opacity: 0,
  });
  const cardGeo = new PlaneGeometry(cardW, cardH);
  const cardMesh = new Mesh(cardGeo, cardMat);
  cardMesh.position.z = 0;
  inner.add(cardMesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (ctx.THREE.SRGBColorSpace) tex.colorSpace = ctx.THREE.SRGBColorSpace;
      cardMat.map = tex;
      cardMat.needsUpdate = true;
    });
  }

  // --- Depth plane 3 (front): accent edge (left bar) ---
  const edgeGeo = new PlaneGeometry(0.06, cardH * 0.92);
  const edgeMat = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    opacity: 0,
  });
  const edgeMesh = new Mesh(edgeGeo, edgeMat);
  edgeMesh.position.set(-cardW / 2 - 0.03, 0, 0.015);
  inner.add(edgeMesh);

  // --- Accent corner detail (top-right) ---
  const cornerGeo = new PlaneGeometry(0.1, 0.1);
  const cornerMat = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    opacity: 0,
  });
  const cornerMesh = new Mesh(cornerGeo, cornerMat);
  cornerMesh.position.set(cardW / 2 - 0.2, cardH / 2 - 0.2, 0.015);
  inner.add(cornerMesh);

  // --- Subtle bottom shadow strip ---
  const shadowGeo = new PlaneGeometry(cardW * 1.05, 0.18);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color(0x000000),
    transparent: true,
    opacity: 0,
    depthWrite: false,
  });
  const shadowMesh = new Mesh(shadowGeo, shadowMat);
  shadowMesh.position.set(0, -cardH / 2 - 0.06, -0.05);
  inner.add(shadowMesh);

  // --- Interactions ---
  let hoverTl = null;
  let pressTl = null;

  group.userData.handlers.onPointerEnter = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(inner.position, { y: 0.15, duration: 0.7, ease: 'power3.out' });
    hoverTl.to(edgeMesh.scale, { y: 1.15, duration: 0.5, ease: 'power2.out' }, 0);
    hoverTl.to(cornerMesh.scale, { x: 1.5, y: 1.5, duration: 0.4, ease: 'power2.out' }, 0);
    hoverTl.to(shadowMat, { opacity: 0.45, duration: 0.4, ease: 'power2.out' }, 0);
  };

  group.userData.handlers.onPointerLeave = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(inner.position, { y: 0, duration: 0.5, ease: 'power3.out' });
    hoverTl.to(edgeMesh.scale, { y: 1.0, duration: 0.4, ease: 'power2.out' }, 0);
    hoverTl.to(cornerMesh.scale, { x: 1.0, y: 1.0, duration: 0.3, ease: 'power2.out' }, 0);
    hoverTl.to(shadowMat, { opacity: 0.0, duration: 0.3, ease: 'power2.out' }, 0);
  };

  group.userData.handlers.onPointerDown = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(inner.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' });
    pressTl.to(inner.scale, { x: 1.0, y: 1.0, duration: 0.2, ease: 'power2.out' });
  };

  group.userData.handlers.onClick = () => {
    ctx.emit('hub-journal.select', { id: config.id });
  };

  // --- Cinematic primitives ---
  const primitiveRefs = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    const result = ctx.primitives[p.name](group, p.params ?? {});
    primitiveRefs.push(result);
  }

  // --- Entrance animation ---
  const entranceTl = gsap.timeline();
  entranceTl.from(inner.position, { y: 0.4, duration: 0.7, ease: 'power3.out' });
  entranceTl.from(inner.scale, { x: 0.96, y: 0.96, duration: 0.9, ease: 'power4.out' }, 0);
  entranceTl.to(cardMat, { opacity: 1.0, duration: 0.6, ease: 'power2.out' }, 0);
  entranceTl.to(glowMat, { opacity: 1.0, duration: 0.7, ease: 'power2.out' }, 0.1);
  entranceTl.to(backdropMat, { opacity: 0.6, duration: 0.5, ease: 'power2.out' }, 0.05);
  entranceTl.to(edgeMat, { opacity: 0.9, duration: 0.4, ease: 'power2.out' }, 0.2);
  entranceTl.to(cornerMat, { opacity: 0.65, duration: 0.4, ease: 'power2.out' }, 0.3);

  // --- Cleanup ---
  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    entranceTl.kill();
    for (const ref of primitiveRefs) {
      try { ref?.timeline?.kill(); } catch (_) {}
      try { ref?.cleanup?.(); } catch (_) {}
    }
    cardGeo.dispose();
    cardMat.dispose();
    glowGeo.dispose();
    glowMat.dispose();
    backdropGeo.dispose();
    backdropMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    cornerGeo.dispose();
    cornerMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
  };

  return group;
}
